/// The fixed part of a generated client (`dartisan client:flutter`):
/// written as `lib/src/runtime.dart` next to the generated models, inputs
/// and resources. Plain Dart on `package:http`, so it works in Flutter
/// (mobile, desktop) and in Dart command-line apps.
///
/// The [Check] implementations mirror the server's rules in
/// `package:daravel/src/validation/rules.dart` line for line; the parity
/// test in `test/client_flutter_test.dart` runs both on the same inputs.
const String clientRuntimeSource = r'''
// GENERATED by `dartisan client:flutter`. Do not edit: regenerate instead.

import 'dart:async';
import 'dart:convert';

import 'package:http/http.dart' as http;

/// Where the bearer token lives between requests. Implement it over
/// `flutter_secure_storage` (or similar) to keep the token across restarts.
abstract interface class TokenStore {
  FutureOr<String?> read();
  FutureOr<void> write(String? token);
}

/// Keeps the token in memory (lost when the app restarts).
final class MemoryTokenStore implements TokenStore {
  MemoryTokenStore([this._token]);

  String? _token;

  @override
  String? read() => _token;

  @override
  void write(String? token) => _token = token;
}

/// A non-2xx response. [message] is Laravel's `message` field.
class ApiException implements Exception {
  ApiException(this.status, this.message, [this.body]);

  final int status;
  final String message;

  /// The decoded JSON body, when there was one.
  final Object? body;

  @override
  String toString() => 'ApiException($status): $message';
}

/// 422: Laravel's validation error body.
final class ValidationException extends ApiException {
  ValidationException(String message, this.errors, [Object? body])
      : super(422, message, body);

  /// Messages per field (`errors.email`), as the server sent them.
  final Map<String, List<String>> errors;

  /// The first message for [field], for a form field's `errorText`.
  String? first(String field) {
    final messages = errors[field];
    return messages == null || messages.isEmpty ? null : messages.first;
  }
}

/// 401: no valid token.
final class UnauthenticatedException extends ApiException {
  UnauthenticatedException(String message, [Object? body])
      : super(401, message, body);
}

/// 429: rate limited; [retryAfter] from the `Retry-After` header.
final class TooManyRequestsException extends ApiException {
  TooManyRequestsException(String message, this.retryAfter, [Object? body])
      : super(429, message, body);

  final Duration? retryAfter;
}

/// One server-sent event (`Response.sse` on the server).
final class SseMessage {
  const SseMessage(this.event, this.data, {this.id});

  final String event;
  final String data;
  final String? id;

  /// [data] decoded as JSON.
  Object? get json => jsonDecode(data);
}

/// A page from Laravel's `paginate()`.
final class Page<T> {
  Page._(this.items, Map<String, Object?> meta, Map<String, Object?> links)
      : currentPage = _int(meta['current_page']) ?? 1,
        lastPage = _int(meta['last_page']) ?? 1,
        perPage = _int(meta['per_page']) ?? items.length,
        total = _int(meta['total']) ?? items.length,
        from = _int(meta['from']),
        to = _int(meta['to']),
        nextPageUrl = links['next'] as String?,
        prevPageUrl = links['prev'] as String?;

  static Page<T> fromJson<T>(
    Object? json,
    T Function(Object? item) item,
  ) {
    final body = _map(json);
    return Page<T>._(
      _list(body['data']).map(item).toList(),
      _map(body['meta']),
      _map(body['links']),
    );
  }

  final List<T> items;
  final int currentPage;
  final int lastPage;
  final int perPage;
  final int total;
  final int? from;
  final int? to;
  final String? nextPageUrl;
  final String? prevPageUrl;

  bool get hasMorePages => currentPage < lastPage;
}

/// A page from Laravel's `simplePaginate()` (no total).
final class SimplePage<T> {
  SimplePage._(this.items, Map<String, Object?> meta, Map<String, Object?> links)
      : currentPage = _int(meta['current_page']) ?? 1,
        perPage = _int(meta['per_page']) ?? items.length,
        nextPageUrl = links['next'] as String?,
        prevPageUrl = links['prev'] as String?;

  static SimplePage<T> fromJson<T>(
    Object? json,
    T Function(Object? item) item,
  ) {
    final body = _map(json);
    return SimplePage<T>._(
      _list(body['data']).map(item).toList(),
      _map(body['meta']),
      _map(body['links']),
    );
  }

  final List<T> items;
  final int currentPage;
  final int perPage;
  final String? nextPageUrl;
  final String? prevPageUrl;

  bool get hasMorePages => nextPageUrl != null;
}

/// A page from Laravel's `cursorPaginate()`.
final class CursorPage<T> {
  CursorPage._(this.items, Map<String, Object?> meta)
      : perPage = _int(meta['per_page']) ?? items.length,
        nextCursor = meta['next_cursor'] as String?,
        prevCursor = meta['prev_cursor'] as String?;

  static CursorPage<T> fromJson<T>(
    Object? json,
    T Function(Object? item) item,
  ) {
    final body = _map(json);
    return CursorPage<T>._(
      _list(body['data']).map(item).toList(),
      _map(body['meta']),
    );
  }

  final List<T> items;
  final int perPage;
  final String? nextCursor;
  final String? prevCursor;

  bool get hasMorePages => nextCursor != null;
}

int? _int(Object? value) => value is num ? value.toInt() : null;

Map<String, Object?> _map(Object? value) =>
    value is Map ? value.cast<String, Object?>() : const <String, Object?>{};

List<Object?> _list(Object? value) =>
    value is List ? value.cast<Object?>() : const <Object?>[];

/// Reads a JSON object (generated `fromJson` constructors use it).
Map<String, Object?> jsonObject(Object? value) {
  if (value is Map) {
    return value.cast<String, Object?>();
  }
  throw FormatException('Expected a JSON object, got ${value.runtimeType}');
}

/// Reads a JSON array.
List<Object?> jsonArray(Object? value) {
  if (value is List) {
    return value.cast<Object?>();
  }
  throw FormatException('Expected a JSON array, got ${value.runtimeType}');
}

/// The HTTP layer of a generated client: JSON in and out, the bearer token
/// from [tokens], and Laravel's error bodies turned into exceptions.
class DaravelClient {
  DaravelClient({
    required String baseUrl,
    http.Client? httpClient,
    TokenStore? tokens,
    Map<String, String> headers = const <String, String>{},
  })  : baseUri = Uri.parse(
          baseUrl.endsWith('/')
              ? baseUrl.substring(0, baseUrl.length - 1)
              : baseUrl,
        ),
        tokens = tokens ?? MemoryTokenStore(),
        _http = httpClient ?? http.Client(),
        _headers = headers;

  final Uri baseUri;
  final TokenStore tokens;
  final http.Client _http;
  final Map<String, String> _headers;

  /// Headers sent with every request (with the token, when there is one).
  Future<Map<String, String>> requestHeaders() async {
    final token = await tokens.read();
    return <String, String>{
      'accept': 'application/json',
      ..._headers,
      if (token != null) 'authorization': 'Bearer $token',
    };
  }

  /// The URL of [path] (`/api/users/1`) with [query].
  Uri uri(String path, [Map<String, Object?>? query]) {
    final values = <String, String>{
      for (final MapEntry(:key, :value) in (query ?? const {}).entries)
        if (value != null) key: '$value',
    };
    return baseUri.replace(
      path: '${baseUri.path}$path',
      queryParameters: values.isEmpty ? null : values,
    );
  }

  /// The `ws://` / `wss://` URL of a WebSocket route. Pass
  /// [requestHeaders] when connecting (`WebSocket.connect(url, headers:)`
  /// from `dart:io`, or `IOWebSocketChannel.connect`), so the route's
  /// `auth` middleware sees the token.
  Uri webSocketUri(String path) {
    final http = uri(path);
    return http.replace(scheme: http.scheme == 'https' ? 'wss' : 'ws');
  }

  /// Sends a request and returns the decoded JSON body (`null` when empty).
  Future<Object?> send(
    String method,
    String path, {
    Map<String, Object?>? query,
    Object? body,
    List<http.MultipartFile> files = const <http.MultipartFile>[],
  }) async {
    final http.BaseRequest request;
    final target = uri(path, query);
    if (files.isNotEmpty) {
      final multipart = http.MultipartRequest(method, target)..files.addAll(files);
      if (body is Map) {
        for (final MapEntry(:key, :value) in body.entries) {
          if (value != null) {
            multipart.fields['$key'] = value is bool ? (value ? '1' : '0') : '$value';
          }
        }
      }
      request = multipart;
    } else {
      final plain = http.Request(method, target);
      if (body != null) {
        plain.headers['content-type'] = 'application/json';
        plain.body = jsonEncode(body);
      }
      request = plain;
    }
    request.headers.addAll(await requestHeaders());
    final response = await http.Response.fromStream(await _http.send(request));
    final text = response.body;
    Object? decoded;
    if (text.isNotEmpty) {
      try {
        decoded = jsonDecode(text);
      } on FormatException {
        decoded = text;
      }
    }
    if (response.statusCode >= 200 && response.statusCode < 300) {
      return decoded;
    }
    final message = decoded is Map && decoded['message'] is String
        ? decoded['message'] as String
        : (response.reasonPhrase ?? 'HTTP ${response.statusCode}');
    switch (response.statusCode) {
      case 422:
        final errors = <String, List<String>>{};
        final raw = decoded is Map ? decoded['errors'] : null;
        if (raw is Map) {
          for (final MapEntry(:key, :value) in raw.entries) {
            errors['$key'] = value is List
                ? [for (final item in value) '$item']
                : ['$value'];
          }
        }
        throw ValidationException(message, errors, decoded);
      case 401:
        throw UnauthenticatedException(message, decoded);
      case 429:
        final seconds = int.tryParse(response.headers['retry-after'] ?? '');
        throw TooManyRequestsException(
          message,
          seconds == null ? null : Duration(seconds: seconds),
          decoded,
        );
      default:
        throw ApiException(response.statusCode, message, decoded);
    }
  }

  /// Listens to a server-sent event stream (`Response.sse`). Ends when the
  /// server sends its end event (`</stream>`) or closes the stream. Send
  /// [lastEventId] when reconnecting to resume after the last `id`.
  Stream<SseMessage> events(
    String path, {
    Map<String, Object?>? query,
    String? lastEventId,
    String endMarker = '</stream>',
  }) async* {
    final request = http.Request('GET', uri(path, query));
    request.headers.addAll(await requestHeaders());
    request.headers['accept'] = 'text/event-stream';
    if (lastEventId != null) {
      request.headers['last-event-id'] = lastEventId;
    }
    final response = await _http.send(request);
    if (response.statusCode != 200) {
      final body = await response.stream.bytesToString();
      throw ApiException(response.statusCode, body.isEmpty ? 'HTTP ${response.statusCode}' : body);
    }
    var event = 'message';
    String? id;
    final data = <String>[];
    await for (final line in response.stream
        .transform(utf8.decoder)
        .transform(const LineSplitter())) {
      if (line.isEmpty) {
        if (data.isNotEmpty) {
          final message = SseMessage(event, data.join('\n'), id: id);
          if (message.data == endMarker) {
            return;
          }
          yield message;
        }
        event = 'message';
        data.clear();
        continue;
      }
      if (line.startsWith(':')) {
        continue; // A comment (heartbeat).
      }
      final colon = line.indexOf(':');
      final field = colon < 0 ? line : line.substring(0, colon);
      var value = colon < 0 ? '' : line.substring(colon + 1);
      if (value.startsWith(' ')) {
        value = value.substring(1);
      }
      switch (field) {
        case 'event':
          event = value;
        case 'data':
          data.add(value);
        case 'id':
          id = value;
      }
    }
  }

  /// Closes the underlying HTTP client.
  void close() => _http.close();
}

// ---------------------------------------------------------------------------
// Client-side validation: the server's rules, checked before sending.
// ---------------------------------------------------------------------------

/// One server validation rule, checked on the device. Messages were
/// resolved by the server's translator when the client was generated, so
/// they read exactly like the 422 the server would send.
final class Check {
  const Check._(
    this.kind, {
    this.message = '',
    this.messages = const <String, String>{},
    this.pattern,
    this.unicode = false,
    this.caseSensitive = true,
    this.negate = false,
    this.a,
    this.b,
    this.values = const <Object?>[],
    this.other,
  });

  const Check.required(String message) : this._('required', message: message);
  const Check.type(String type, String message) : this._(type, message: message);
  const Check.pattern(
    String name,
    String pattern,
    String message, {
    bool unicode = false,
    bool caseSensitive = true,
    bool negate = false,
  }) : this._(
          name,
          message: message,
          pattern: pattern,
          unicode: unicode,
          caseSensitive: caseSensitive,
          negate: negate,
        );
  const Check.url(String message) : this._('url', message: message);
  const Check.lowercase(String message) : this._('lowercase', message: message);
  const Check.uppercase(String message) : this._('uppercase', message: message);

  /// `min`, `max`, `between` and `size`: [messages] keyed by the size kind
  /// (`string`, `numeric`, `array`), which follows the value's type as on
  /// the server.
  const Check.size(String rule, Map<String, String> messages, {num? a, num? b})
      : this._(rule, messages: messages, a: a, b: b);
  const Check.digits(String message, int length)
      : this._('digits', message: message, a: length);
  const Check.digitsBetween(String message, int min, int max)
      : this._('digits_between', message: message, a: min, b: max);
  const Check.oneOf(String message, List<Object?> values, {bool negate = false})
      : this._('in', message: message, values: values, negate: negate);
  const Check.startsWith(String message, List<String> values)
      : this._('starts_with', message: message, values: values);
  const Check.endsWith(String message, List<String> values)
      : this._('ends_with', message: message, values: values);

  /// `confirmed`: [other] must equal the value (`password_confirmation`).
  const Check.confirmed(String message, String other)
      : this._('confirmed', message: message, other: other);

  /// `Rules.password()`: [messages] keyed `string`, `min`, `letters`,
  /// `mixed`, `numbers`, `symbols`; [extras] are the enabled extras.
  const Check.password(Map<String, String> messages, int min, List<String> extras)
      : this._('password', messages: messages, a: min, values: extras);

  final String kind;

  /// The failure message (rules with one message).
  final String message;

  /// Failure messages by variant (size kind, password requirement).
  final Map<String, String> messages;
  final String? pattern;
  final bool unicode;
  final bool caseSensitive;
  final bool negate;
  final num? a;
  final num? b;
  final List<Object?> values;
  final String? other;

  /// Whether this runs for absent and empty values (`required`).
  bool get implicit => kind == 'required';

  /// The failure message, or `null` when [value] passes. [data] holds the
  /// other fields (for `confirmed`); [numeric] is whether the field also
  /// has a `numeric` or `integer` rule, which makes the size rules measure
  /// a string by its value, as on the server.
  String? apply(Object? value, Map<String, Object?> data, {bool numeric = false}) {
    switch (kind) {
      case 'required':
        return isEmptyValue(value) ? message : null;
      case 'string':
        return value is String ? null : message;
      case 'integer':
        return _asInt(value) == null ? message : null;
      case 'numeric':
        return _asNum(value) == null ? message : null;
      case 'boolean':
        return _asBool(value) == null ? message : null;
      case 'array':
        return value is List ? null : message;
      case 'url':
        if (value is! String || value.length > 8192) {
          return message;
        }
        final uri = Uri.tryParse(value);
        final ok = uri != null &&
            (uri.scheme == 'http' || uri.scheme == 'https') &&
            uri.host.isNotEmpty;
        return ok ? null : message;
      case 'lowercase':
        return value is String && value == value.toLowerCase() ? null : message;
      case 'uppercase':
        return value is String && value == value.toUpperCase() ? null : message;
      case 'min' || 'max' || 'between' || 'size':
        final size = _sizeOf(value, numeric: numeric);
        final ok = size != null &&
            switch (kind) {
              'min' => size >= a!,
              'max' => size <= a!,
              'between' => size >= a! && size <= b!,
              _ => size == a!,
            };
        return ok
            ? null
            : (messages[_sizeKind(value, numeric: numeric)] ?? messages['string']);
      case 'digits':
        final text = '$value';
        return RegExp(r'^\d+$').hasMatch(text) && text.length == a ? null : message;
      case 'digits_between':
        final text = '$value';
        return RegExp(r'^\d+$').hasMatch(text) && text.length >= a! && text.length <= b!
            ? null
            : message;
      case 'in':
        final contained = values.any((v) => v == value || '$v' == '$value');
        return contained != negate ? null : message;
      case 'starts_with':
        return value is String && values.any((v) => value.startsWith('$v')) ? null : message;
      case 'ends_with':
        return value is String && values.any((v) => value.endsWith('$v')) ? null : message;
      case 'confirmed':
        return '${_dig(data, other!)}' == '$value' ? null : message;
      case 'password':
        if (value is! String) {
          return messages['string'];
        }
        if (value.runes.length < a!) {
          return messages['min'];
        }
        if (values.contains('letters') && !RegExp(r'\p{L}', unicode: true).hasMatch(value)) {
          return messages['letters'];
        }
        if (values.contains('mixed') &&
            !(RegExp(r'\p{Ll}', unicode: true).hasMatch(value) &&
                RegExp(r'\p{Lu}', unicode: true).hasMatch(value))) {
          return messages['mixed'];
        }
        if (values.contains('numbers') && !RegExp(r'\p{N}', unicode: true).hasMatch(value)) {
          return messages['numbers'];
        }
        if (values.contains('symbols') && !RegExp(r'[\p{P}\p{S}]', unicode: true).hasMatch(value)) {
          return messages['symbols'];
        }
        return null;
      default:
        // A pattern rule (email, uuid, alpha, regex, ...).
        if (value is! String) {
          return message;
        }
        final matches = RegExp(pattern!, unicode: unicode, caseSensitive: caseSensitive).hasMatch(value);
        return matches != negate ? null : message;
    }
  }
}

/// The checks of one field, run in the server's order and with its rules
/// for absent, empty and `nullable` values.
final class FieldChecks {
  const FieldChecks(
    this.checks, {
    this.nullable = false,
    this.sometimes = false,
    this.bail = false,
  });

  final List<Check> checks;
  final bool nullable;
  final bool sometimes;

  /// Stop at the first failure (`bail`).
  final bool bail;

  /// Every failure message for [field] in [data] (the server's 422 list).
  List<String> run(Map<String, Object?> data, String field) {
    final present = _exists(data, field);
    final value = present ? _dig(data, field) : null;
    if (sometimes && !present) {
      return const <String>[];
    }
    final emptyString = value is String && value.trim().isEmpty;
    final numeric =
        checks.any((check) => check.kind == 'numeric' || check.kind == 'integer');
    final failures = <String>[];
    for (final check in checks) {
      if (!check.implicit) {
        if (!present || emptyString) {
          continue;
        }
        if (value == null && nullable) {
          continue;
        }
      }
      final failure = check.apply(value, data, numeric: numeric);
      if (failure != null) {
        failures.add(failure);
        if (bail) {
          break;
        }
      }
    }
    return failures;
  }

  /// The first failure of a single [value], for `TextFormField.validator`.
  /// Rules that compare fields (`confirmed`) need [data] and are skipped
  /// without it.
  String? first(Object? value, [Map<String, Object?>? data]) {
    final values = <String, Object?>{...?data, '_': value};
    final list = FieldChecks(
      [
        for (final check in checks)
          if (check.kind != 'confirmed' || data != null) check,
      ],
      nullable: nullable,
      bail: true,
    ).run(values, '_');
    return list.isEmpty ? null : list.first;
  }
}

/// Runs [rules] over [data]: the messages per field, empty when valid.
Map<String, List<String>> validateAll(
  Map<String, FieldChecks> rules,
  Map<String, Object?> data,
) {
  final errors = <String, List<String>>{};
  for (final MapEntry(key: field, value: checks) in rules.entries) {
    final failures = checks.run(data, field);
    if (failures.isNotEmpty) {
      errors[field] = failures;
    }
  }
  return errors;
}

/// The server's notion of an empty value (`required`).
bool isEmptyValue(Object? value) => switch (value) {
      null => true,
      String() => value.trim().isEmpty,
      List() => value.isEmpty,
      Map() => value.isEmpty,
      _ => false,
    };

int? _asInt(Object? value) => switch (value) {
      int() => value,
      double() when value == value.truncateToDouble() => value.toInt(),
      String() => int.tryParse(value.trim()),
      _ => null,
    };

num? _asNum(Object? value) => switch (value) {
      num() => value,
      String() => num.tryParse(value.trim()),
      _ => null,
    };

bool? _asBool(Object? value) => switch (value) {
      bool() => value,
      1 || '1' || 'true' => true,
      0 || '0' || 'false' => false,
      _ => null,
    };

num? _sizeOf(Object? value, {bool numeric = false}) => switch (value) {
      num() => value,
      String() when numeric => num.tryParse(value.trim()) ?? value.runes.length,
      String() => value.runes.length,
      List() => value.length,
      Map() => value.length,
      _ => null,
    };

String _sizeKind(Object? value, {bool numeric = false}) => switch (value) {
      num() => 'numeric',
      String() when numeric && num.tryParse(value.trim()) != null => 'numeric',
      List() || Map() => 'array',
      _ => 'string',
    };

bool _exists(Map<String, Object?> data, String path) {
  Object? current = data;
  for (final segment in path.split('.')) {
    if (current is Map && current.containsKey(segment)) {
      current = current[segment];
    } else {
      return false;
    }
  }
  return true;
}

Object? _dig(Map<String, Object?> data, String path) {
  Object? current = data;
  for (final segment in path.split('.')) {
    if (current is Map) {
      current = current[segment];
    } else {
      return null;
    }
  }
  return current;
}
''';
